package org.pocketlore.app;
import android.app.Instrumentation;import android.os.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
/** Current APK plus real optional assets with the retained full task303 catalog. */
final class AttachmentBudget {
 static volatile boolean sampling;static volatile long peakBytes,peakPss,peakAllocated;static volatile String sampleFailure;
 static void run(Instrumentation test,Bundle args){Bundle done=new Bundle();JSONObject r=new JSONObject();File root=test.getTargetContext().getFilesDir();File out=new File(root,args.getString("directory"));out.mkdirs();Thread sampler=null;try{
  String model=BroadPack.hash(new File(root,"model.gguf")),catalog=BroadPack.hash(new File(root,"scale-library/catalog.json"));
  sampling=true;sampler=new Thread(()->{while(sampling){try{peakBytes=Math.max(peakBytes,SharedShardUpdate.uniqueBytes(root.getParentFile()));long allocated=0;try(java.util.stream.Stream<Path> paths=Files.walk(root.getParentFile().toPath())){for(Iterator<Path> it=paths.iterator();it.hasNext();){try{allocated+=android.system.Os.stat(it.next().toString()).st_blocks*512;}catch(android.system.ErrnoException e){if(e.errno!=android.system.OsConstants.ENOENT)throw e;}}}peakAllocated=Math.max(peakAllocated,allocated);peakPss=Math.max(peakPss,Debug.getPss());Thread.sleep(20);}catch(Exception e){sampleFailure=e.toString();return;}}});sampler.start();
  File input=new File(root,"attachments-budget-input");
  for(boolean speech:new boolean[]{false,true}){File f=new File(input,speech?"ggml-tiny.en.bin":"eng.traineddata");try(InputStream in=new FileInputStream(f)){AttachmentAssets.install(root,speech,in,()->false);}if(!AttachmentAssets.available(root,speech))throw new IOException("Model verification");Files.delete(f.toPath());}
  ScaleLibrary lib=new ScaleLibrary(root);ScaleLibrary.Entry wiki=null,places=null;int shards=0;JSONArray ids=new JSONArray();for(ScaleLibrary.Entry e:lib.entries()){shards+=e.manifest.getJSONArray("shards").length();ids.put(e.id);if(e.kind().equals("wiki"))wiki=e;else places=e;}if(shards!=31||wiki==null||places==null)throw new IOException("Full retained inventory required");
  long start=System.nanoTime();List<ScaleWiki.Hit> hits=ScaleWiki.search(wiki,"Acid",()->false);if(hits.isEmpty())throw new IOException("Reader missing");ScaleWiki.Hit h=hits.get(0);ScaleWiki.Read read=ScaleWiki.read(h,test.getTargetContext().getCacheDir(),()->false);r.put("wiki_source",ScaleWiki.detail(h,read)).put("wiki_ms",(System.nanoTime()-start)/1e6);if(h.mayGenerate())throw new IOException("Rights gate changed");
  start=System.nanoTime();List<ScalePlaces.City> cities=ScalePlaces.cities(places,"Mexico City",()->false);if(cities.isEmpty())throw new IOException("City missing");ScalePlaces.City c=cities.get(0);List<ScalePlaces.Hit> pois=ScalePlaces.nearby(places,c.lat,c.lon,1,"restaurant",()->false);if(pois.isEmpty())throw new IOException("Places reader empty");r.put("places_ms",(System.nanoTime()-start)/1e6).put("places_source",ScalePlaces.detail(pois.get(0),()->false)).put("places_candidates",pois.size());
  AttachmentEngine.Result ocr=AttachmentEngine.image(root,Files.readAllBytes(new File(input,"text.png").toPath()),"budget fixture",()->false);if(!ocr.text.contains("OFFLINE LIBRARY"))throw new IOException("OCR coexistence");r.put("ocr",ocr.text);
  start=System.nanoTime();AttachmentEngine.Result speech=AttachmentEngine.audio(root,Files.readAllBytes(new File(input,"speech.wav").toPath()),"budget fixture",()->false);if(!speech.text.contains("country"))throw new IOException("Speech coexistence");r.put("speech",speech.text).put("speech_ms",(System.nanoTime()-start)/1e6);
  if(!model.equals(BroadPack.hash(new File(root,"model.gguf")))||!catalog.equals(BroadPack.hash(new File(root,"scale-library/catalog.json"))))throw new IOException("Saved identity changed");
  sampling=false;sampler.join();if(sampleFailure!=null||peakBytes==0||peakAllocated==0)throw new IOException("Sampler failed: "+sampleFailure);r.put("status","PASS").put("shards",shards).put("collection_ids",ids).put("model_sha256",model).put("catalog_sha256",catalog).put("app_logical_bytes",SharedShardUpdate.uniqueBytes(root.getParentFile())).put("sampled_import_app_peak_bytes",peakBytes).put("sampled_import_app_allocated_peak_bytes",peakAllocated).put("sampled_pss_peak_kib",peakPss).put("optional_bytes",AttachmentAssets.bytes(false)+AttachmentAssets.bytes(true)).put("proc_status",new String(Files.readAllBytes(Paths.get("/proc/self/status")),java.nio.charset.StandardCharsets.UTF_8));done.putString("stream","ATTACHMENTS_BUDGET_PASS");
 }catch(Throwable e){try{r.put("status","FAIL").put("error",android.util.Log.getStackTraceString(e));}catch(Exception ignored){}done.putString("stream",e.toString());}finally{sampling=false;try{if(sampler!=null)sampler.join();Files.write(new File(out,"budget.json").toPath(),r.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception ignored){}test.finish(r.optString("status").equals("PASS")?-1:0,done);}}
}
